select sum(total_amount) from biz_purchase_order

    and deleted = false

        and order_no like concat('%', #{orderNo}, '%')


        and name like concat('%', #{name}, '%')


        and supplier_id = #{supplierId}


        and supplier_name like concat('%', #{supplierName}, '%')


        and purchaser_user_name like concat('%', #{purchaserUserName}, '%')


        and purchase_user_id = #{purchaseUserId}


        and expected_time between
        #{expectedTime[0], javaType=java.time.LocalDateTime, jdbcType=TIMESTAMP}
        and
        #{expectedTime[1], javaType=java.time.LocalDateTime, jdbcType=TIMESTAMP}


        and actual_time between
        #{actualTime[0], javaType=java.time.LocalDateTime, jdbcType=TIMESTAMP}
        and
        #{actualTime[1], javaType=java.time.LocalDateTime, jdbcType=TIMESTAMP}


        and order_status = #{orderStatus}


        AND create_time BETWEEN #{createTime[0], javaType=java.time.LocalDateTime, jdbcType=TIMESTAMP} AND
        #{createTime[1], javaType=java.time.LocalDateTime, jdbcType=TIMESTAMP}
